using System;
using System.Globalization;

public static class Program
{
    private const double Pi = 3.141592653589793;
    private const double SolarMass = 4.0 * Pi * Pi;
    private const double DaysPerYear = 365.24;
    private const double Dt = 0.01;

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);

        double[] x = new double[5];
        double[] y = new double[5];
        double[] z = new double[5];
        double[] vx = new double[5];
        double[] vy = new double[5];
        double[] vz = new double[5];
        double[] mass = new double[5];

        InitBodies(x, y, z, vx, vy, vz, mass);

        OffsetMomentum(vx, vy, vz, mass);

        Console.WriteLine(Energy(x, y, z, vx, vy, vz, mass).ToString("F9", CultureInfo.InvariantCulture));

        for (int i = 0; i < n; i++)
            Advance(x, y, z, vx, vy, vz, mass, Dt);

        Console.WriteLine(Energy(x, y, z, vx, vy, vz, mass).ToString("F9", CultureInfo.InvariantCulture));
    }

    private static void InitBodies(double[] x, double[] y, double[] z, double[] vx, double[] vy, double[] vz, double[] mass)
    {
        // Sun
        x[0] = 0; y[0] = 0; z[0] = 0;
        vx[0] = 0; vy[0] = 0; vz[0] = 0;
        mass[0] = SolarMass;

        // Jupiter
        x[1] = 4.84143144246472090e+00;
        y[1] = -1.16032004402742839e+00;
        z[1] = -1.03622044471123109e-01;
        vx[1] = 1.66007664274403694e-03 * DaysPerYear;
        vy[1] = 7.69901118419740425e-03 * DaysPerYear;
        vz[1] = -6.90460016972063023e-05 * DaysPerYear;
        mass[1] = 9.54791938424326609e-04 * SolarMass;

        // Saturn
        x[2] = 8.34336671824457987e+00;
        y[2] = 4.12479856412430479e+00;
        z[2] = -4.03523417114321381e-01;
        vx[2] = -2.76742510726862411e-03 * DaysPerYear;
        vy[2] = 4.99852801234917238e-03 * DaysPerYear;
        vz[2] = 2.30417297573763929e-05 * DaysPerYear;
        mass[2] = 2.85885980666130812e-04 * SolarMass;

        // Uranus
        x[3] = 1.28943695621391310e+01;
        y[3] = -1.51111514016986312e+01;
        z[3] = -2.23307578892655734e-01;
        vx[3] = 2.96460137564761618e-03 * DaysPerYear;
        vy[3] = 2.37847173959480950e-03 * DaysPerYear;
        vz[3] = -2.96589568540237556e-05 * DaysPerYear;
        mass[3] = 4.36624404335156298e-05 * SolarMass;

        // Neptune
        x[4] = 1.53796971148509165e+01;
        y[4] = -2.59193146099879641e+01;
        z[4] = 1.79258772950371181e-01;
        vx[4] = 2.68067772490389322e-03 * DaysPerYear;
        vy[4] = 1.62824170038242295e-03 * DaysPerYear;
        vz[4] = -9.51592254519715870e-05 * DaysPerYear;
        mass[4] = 5.15138902046611451e-05 * SolarMass;
    }

    private static void OffsetMomentum(double[] vx, double[] vy, double[] vz, double[] mass)
    {
        double px = 0, py = 0, pz = 0;
        for (int i = 0; i < 5; i++)
        {
            px += vx[i] * mass[i];
            py += vy[i] * mass[i];
            pz += vz[i] * mass[i];
        }

        vx[0] = -px / SolarMass;
        vy[0] = -py / SolarMass;
        vz[0] = -pz / SolarMass;
    }

    private static void Advance(double[] x, double[] y, double[] z, double[] vx, double[] vy, double[] vz, double[] mass, double dt)
    {
        for (int i = 0; i < 5; i++)
        {
            for (int j = i + 1; j < 5; j++)
            {
                double dx = x[i] - x[j];
                double dy = y[i] - y[j];
                double dz = z[i] - z[j];

                double d2 = dx * dx + dy * dy + dz * dz;
                double dist = Math.Sqrt(d2);
                double mag = dt / (d2 * dist);

                double miMag = mass[j] * mag;
                double mjMag = mass[i] * mag;

                vx[i] -= dx * miMag;
                vy[i] -= dy * miMag;
                vz[i] -= dz * miMag;

                vx[j] += dx * mjMag;
                vy[j] += dy * mjMag;
                vz[j] += dz * mjMag;
            }
        }

        for (int i = 0; i < 5; i++)
        {
            x[i] += dt * vx[i];
            y[i] += dt * vy[i];
            z[i] += dt * vz[i];
        }
    }

    private static double Energy(double[] x, double[] y, double[] z, double[] vx, double[] vy, double[] vz, double[] mass)
    {
        double e = 0.0;

        for (int i = 0; i < 5; i++)
        {
            e += 0.5 * mass[i] * (vx[i] * vx[i] + vy[i] * vy[i] + vz[i] * vz[i]);
            for (int j = i + 1; j < 5; j++)
            {
                double dx = x[i] - x[j];
                double dy = y[i] - y[j];
                double dz = z[i] - z[j];
                e -= (mass[i] * mass[j]) / Math.Sqrt(dx * dx + dy * dy + dz * dz);
            }
        }

        return e;
    }
}

